let currentFilter = 'all';
let currentSearch = '';
const grid = document.getElementById('loreGrid');
function renderLoreGrid() {
 const filtered = loreEntries.filter(entry => (currentFilter === 'all' || entry.type === currentFilter) && (entry.name + ' ' + entry.summary).toLowerCase().includes(currentSearch.toLowerCase()));
 document.getElementById('codex-count').textContent = `${filtered.length} ${filtered.length === 1 ? 'entry' : 'entries'}`;
 grid.innerHTML = filtered.length ? filtered.map(entry => `<a class="lore-card" href="/${entry.id}" ${entry.faction ? `data-faction="${entry.faction.toLowerCase().replace(/\s/g, '-')}"` : ''}><img src="/${entry.image}" alt="${entry.name}" width="65" height="80" loading="lazy" decoding="async"><div class="lore-card-content"><h3>${entry.name}</h3><span class="lore-tag">${entry.type}</span>${entry.faction ? `<span class="lore-tag">${entry.faction}</span>` : ''}<p>${entry.summary}</p></div></a>`).join('') : '<p class="no-results">No entries match that search. Try another name or choose All.</p>';
 document.getElementById('mapHeroCard').hidden = currentFilter !== 'all' || currentSearch !== '';
}
document.querySelectorAll('.filter-btn').forEach(button => button.addEventListener('click', () => {
 document.querySelectorAll('.filter-btn').forEach(other => { other.classList.toggle('active',other === button); other.setAttribute('aria-pressed', String(other === button)); }); currentFilter = button.dataset.filter; renderLoreGrid();
}));
document.getElementById('searchBox').addEventListener('input', event => { currentSearch = event.target.value.trim(); renderLoreGrid(); });
document.getElementById('codex-archive').addEventListener('toggle', () => { if (!grid.children.length) renderLoreGrid(); });
document.getElementById('blogPosts').innerHTML = updates.map(update => `<article><time>${update.date}</time><p>${update.content}</p><a class="text-link" href="${update.link}" target="_blank" rel="noopener noreferrer">${update.linkText} ↗</a></article>`).join('');
